package com.graphhopper.routing.querygraph;

import com.graphhopper.routing.ch.PrepareEncoder;
import com.graphhopper.routing.ev.BooleanEncodedValue;
import com.graphhopper.routing.ev.DecimalEncodedValue;
import com.graphhopper.routing.ev.TurnCost;
import com.graphhopper.routing.util.AllEdgesIterator;
import com.graphhopper.routing.util.EdgeFilter;
import com.graphhopper.routing.weighting.Weighting;
import com.graphhopper.storage.*;
import com.graphhopper.util.EdgeIterator;
import com.graphhopper.util.EdgeIteratorState;
import com.graphhopper.util.GHUtility;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.Arrays;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class QueryRoutingCHGraphclose_IntObjectMapclearFikaTest {

    @Test
    public void testClose() {
        // Create real objects for the dependencies
        BaseGraph baseGraph = createBaseGraph();
        CHStorage chStorage = createCHStorage();
        CHStorageBuilder chStorageBuilder = createCHStorageBuilder(chStorage);
        RoutingCHGraph routingCHGraph = createRoutingCHGraph(baseGraph, chStorage, chStorageBuilder);

        // Create the object under test
        QueryRoutingCHGraph queryGraph = new QueryRoutingCHGraph(routingCHGraph, 1);

        // Execute the entry point method
        queryGraph.close();
    }

    private BaseGraph createBaseGraph() {
        BooleanEncodedValue accessEnc = PrepareEncoder.getAccessEnc("car");
        DecimalEncodedValue speedEnc = PrepareEncoder.getSpeedEnc("car");
        EncodingManager encodingManager = EncodingManager.start()
                .add(accessEnc)
                .add(speedEnc)
                .addTurnCostEncodedValue(TurnCost.create("car", 1))
                .build();
        return new BaseGraph.Builder(encodingManager).create();
    }

    private CHStorage createCHStorage() {
        BooleanEncodedValue accessEnc = PrepareEncoder.getAccessEnc("car");
        DecimalEncodedValue speedEnc = PrepareEncoder.getSpeedEnc("car");
        EncodingManager encodingManager = EncodingManager.start()
                .add(accessEnc)
                .add(speedEnc)
                .addTurnCostEncodedValue(TurnCost.create("car", 1))
                .build();
        return CHStorage.fromGraph(new BaseGraph.Builder(encodingManager).create());
    }

    private CHStorageBuilder createCHStorageBuilder(CHStorage chStorage) {
        return new CHStorageBuilder(chStorage);
    }

    private RoutingCHGraph createRoutingCHGraph(BaseGraph baseGraph, CHStorage chStorage, CHStorageBuilder chStorageBuilder) {
        // Create a mock Weighting
        Weighting weighting = mock(Weighting.class);
        BooleanEncodedValue accessEnc = PrepareEncoder.getAccessEnc("car");
        DecimalEncodedValue speedEnc = PrepareEncoder.getSpeedEnc("car");
        when(weighting.getFlagEncoder()).thenReturn(new EncodingManager.Builder().add(accessEnc).add(speedEnc).build().getEncoder("car"));

        // Build the CHStorage
        chStorageBuilder.setIdentityLevels();
        chStorageBuilder.create(10);

        // Create a real RoutingCHGraphImpl
        return RoutingCHGraphImpl.fromGraph(baseGraph, chStorage, weighting);
    }
}

