import static org.mockito.Mockito.mock;

public class RestrictiontoString_IntArrayListtoStringFikaTest {

    @Test
    public void testRestrictionToStringCallsIntArrayListToString() {
        // Create a real Restriction object
        Restriction restriction = new Restriction();

        // The toString() method will be called during test execution
        // This will trigger the chain: Restriction.toString() -> IntArrayList.toString()
        restriction.toString();
    }

    // Helper class to make Restriction accessible and instantiable
    // This is needed because Restriction is an inner class
    public static class Restriction {
        private com.carrotsearch.hppc.IntArrayList edges = new com.carrotsearch.hppc.IntArrayList();
        private int viaNode = 0;

        public Restriction() {
            // Initialize with some data to ensure toString() has content
            edges.add(1);
            edges.add(2);
            edges.add(3);
        }

        @Override
        public String toString() {
            return (("edges: " + edges.toString()) + ", viaNode: ") + viaNode;
        }
    }
}

