            @Override public boolean isBackward(EdgeFilter filter) { return true; }
        };

        when(graph.getEdgeIteratorState(0, 0)).thenReturn(mockEdge);

        CHPathCalculator calculator = new CHPathCalculator(routingCHGraph);

        try {
            List<Path> paths = calculator.calcPaths(0, 1, edgeRestrictions);
        } catch (IllegalArgumentException e) {
            // Expected exception when unfavoredEdges is not empty
        }
    }
}

