package com.graphhopper.isochrone.algorithm;

import com.graphhopper.isochrone.algorithm.ContourBuilder;
import com.graphhopper.routing.ev.BooleanEncodedValue;
import com.graphhopper.routing.ev.DecimalEncodedValue;
import com.graphhopper.routing.ev.DecimalEncodedValueImpl;
import com.graphhopper.routing.ev.SimpleBooleanEncodedValue;
import com.graphhopper.routing.util.EncodingManager;
import com.graphhopper.storage.BaseGraph;
import com.graphhopper.util.EdgeIteratorState;
import com.graphhopper.util.QuadEdge;
import com.graphhopper.util.ReadableQuadEdge;
import org.junit.jupiter.api.Test;
import org.locationtech.jts.geom.Coordinate;
import org.locationtech.jts.geom.GeometryFactory;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.function.ToIntBiFunction;

public class ContourBuildercomputeIsoline_GeometryFactorycreateLinearRingFikaTest {

    @Test
    public void testComputeIsolineTriggersCreateLinearRing() {
        // Create a minimal graph with at least one edge
        BooleanEncodedValue accessEnc = new SimpleBooleanEncodedValue("access", true);
        DecimalEncodedValue speedEnc = new DecimalEncodedValueImpl("speed", 5, 5, false);
        EncodingManager encodingManager = EncodingManager.start().add(accessEnc).add(speedEnc).build();
        BaseGraph graph = new BaseGraph.Builder(encodingManager).create();

        // Add a simple triangle to ensure triangulation produces edges
        graph.edge(0, 1).setDistance(1);
        graph.edge(1, 2).setDistance(1);
        graph.edge(2, 0).setDistance(1);

        // Get triangulation edges
        List<ReadableQuadEdge> edges = new ArrayList<>();
        for (EdgeIteratorState edge : graph.getAllEdges()) {
            // Create simple QuadEdge-like structure
            QuadEdge qe = new QuadEdge(
                graph.getNodeAccess().getLat(edge.getBaseNode()),
                graph.getNodeAccess().getLon(edge.getBaseNode()),
                graph.getNodeAccess().getLat(edge.getAdjNode()),
                graph.getNodeAccess().getLon(edge.getAdjNode())
            );
            edges.add(qe);
        }

        // Create ContourBuilder with real GeometryFactory
        ContourBuilder contourBuilder = new ContourBuilder(new GeometryFactory());

        // Create a cut function that returns non-zero for some edges
        ToIntBiFunction<Object, Object> cutFunction = (v1, v2) -> {
            // Return alternating values to trigger the path
            return 1;
        };

        // Execute the entry point
        contourBuilder.computeIsoline(cutFunction, edges);
    }
}

