import com.graphhopper.routing.subnetwork.ConnectedComponents;
import com.graphhopper.routing.subnetwork.TarjanSCC;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.Arrays;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

public class LandmarkStoragecreateLandmarks_IntArrayListsizeFikaTest {

    @Test
    public void testCreateLandmarksInvokesIntArrayListSize() {
        // Create real graph with minimal structure
        Directory dir = new RAMDirectory();
        BaseGraph graph = new BaseGraph.Builder(1).setDir(dir).create();
        // Add at least one node so getNodes() > 0
        graph.getNodeAccess().setNode(0, 0, 0);

        // Create real LMConfig
        LMConfig lmConfig = new LMConfig("car", Mockito.mock(Weighting.class));

        // Mock EncodedValueLookup to provide the required BooleanEncodedValue
        EncodedValueLookup encodedValueLookup = Mockito.mock(EncodedValueLookup.class);
        BooleanEncodedValue edgeInSubnetworkEnc = Mockito.mock(BooleanEncodedValue.class);
        when(encodedValueLookup.hasEncodedValue(any())).thenReturn(true);
        when(encodedValueLookup.getBooleanEncodedValue(any())).thenReturn(edgeInSubnetworkEnc);

        // Create real LandmarkStorage with minimal required parameters
        LandmarkStorage storage = new LandmarkStorage(
                dir,
                graph,
                lmConfig,
                2, // landmarks
                1, // minimumNodes
                false // logDetails
        );

        // Inject the mocked encodedValueLookup via reflection
        try {
            java.lang.reflect.Field field = LandmarkStorage.class.getDeclaredField("encodedValueLookup");
            field.setAccessible(true);
            field.set(storage, encodedValueLookup);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Execute the entry point method
        storage.createLandmarks();
    }
}

