package com.graphhopper.routing;

import com.graphhopper.routing.weighting.Weighting;
import com.graphhopper.storage.Graph;
import com.graphhopper.util.GHUtility;
import com.carrotsearch.hppc.IntObjectMap;
import com.carrotsearch.hppc.IntSet;
import com.carrotsearch.hppc.predicates.IntObjectPredicate;
import com.graphhopper.routing.ch.CHRoutingAlgorithmFactory;
import com.graphhopper.routing.weighting.ShortestWeighting;
import com.graphhopper.storage.BaseGraph;
import com.graphhopper.storage.RAMDirectory;
import com.graphhopper.util.EdgeIteratorState;
import com.graphhopper.util.PMap;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.List;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.when;

public class AlternativeRoutecalcAlternatives_IntObjectMapforEachFikaTest {

    @Test
    public void testCalcAlternatives() {
        // Create a minimal graph
        BaseGraph graph = new BaseGraph.Builder(1).create();
        Weighting weighting = new ShortestWeighting();
        CHRoutingAlgorithmFactory factory = new CHRoutingAlgorithmFactory(graph, weighting);

        // Create a simple path
        EdgeIteratorState edge1 = graph.edge(0, 1).setDistance(100);
        Path path = new Path(graph, weighting);
        path.setEdgeIds(edge1.getEdge());
        path.setFromNode(0);
        path.setEndNode(1);

        // Create AlternativeRoute instance
        AlternativeRoute altRoute = new AlternativeRoute(graph, weighting, new PMap());

        // Mock the bestWeightMapFrom to ensure forEach is called
        IntObjectMap<SPTEntry> mockMap = Mockito.mock(IntObjectMap.class);
        when(mockMap.forEach(any(IntObjectPredicate.class))).thenAnswer(invocation -> {
            IntObjectPredicate<SPTEntry> predicate = invocation.getArgument(0);
            // Simulate a single call to the predicate
            predicate.apply(1, new SPTEntry(edge1.getEdge(), 1, 100.0));
            return true;
        });

        // Use reflection to set the private field
        try {
            java.lang.reflect.Field field = AlternativeRoute.class.getDeclaredField("bestWeightMapFrom");
            field.setAccessible(true);
            field.set(altRoute, mockMap);

            // Also set bestWeightMapTo to avoid NPE
            IntObjectMap<SPTEntry> mockMapTo = Mockito.mock(IntObjectMap.class);
            when(mockMapTo.get(anyInt())).thenReturn(new SPTEntry(edge1.getEdge(), 1, 50.0));
            java.lang.reflect.Field fieldTo = AlternativeRoute.class.getDeclaredField("bestWeightMapTo");
            fieldTo.setAccessible(true);
            fieldTo.set(altRoute, mockMapTo);

            // Set traversalMode
            java.lang.reflect.Field traversalModeField = AlternativeRoute.class.getDeclaredField("traversalMode");
            traversalModeField.setAccessible(true);
            traversalModeField.set(altRoute, com.graphhopper.routing.util.TraversalMode.NODE_BASED);

        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Call the entry point method
        List<AlternativeInfo> result = altRoute.calcAlternatives(
            path, 
            5, 
            1.4, 
            0.8, 
            0.9, 
            0.7, 
            0.1, 
            0.5
        );
    }

    // Minimal SPTEntry class for compilation
    private static class SPTEntry {
        int edge;
        int adjNode;
        double weight;

        SPTEntry(int edge, int adjNode, double weight) {
            this.edge = edge;
            this.adjNode = adjNode;
            this.weight = weight;
        }

        double getWeightOfVisitedPath() { return weight; }
        SPTEntry getParent() { return null; }
    }

    // Minimal Path class for compilation
    private static class Path {
        private final Graph graph;
        private final Weighting weighting;
        private int fromNode;
        private int endNode;
        private int edgeId;

        Path(Graph graph, Weighting weighting) {
            this.graph = graph;
            this.weighting = weighting;
        }

        void setEdgeIds(int edgeId) { this.edgeId = edgeId; }
        void setFromNode(int node) { this.fromNode = node; }
        void setEndNode(int node) { this.endNode = node; }
        double getWeight() { return 100.0; }
    }

    // Minimal AlternativeInfo class for compilation
    private static class AlternativeInfo {
        AlternativeInfo(double sortBy, Path path, Object fromEE, Object toEE, double shareWeight, List<String> altNames) {}
    }
}

