        throw new IllegalStateException((((((("Incompatible encoding version. You need to use the same GraphHopper version you used to import the graph" + " in '") + properties.getDirectory().getLocation()) + "', delete the folder, or run a new import with another location. ") + " Stored encoding version: ") + (versionStr.isEmpty() ? "missing" : versionStr)) + ", used encoding version: ") + Constants.VERSION_EM);
