    public void testComputeIsolineTriggersPreparedPolygonGetGeometry() {
        // Create a minimal graph with one triangle
        EncodingManager encodingManager = EncodingManager.create("car");
        BaseGraph graph = new BaseGraph.Builder(encodingManager).create();
        NodeAccess na = graph.getNodeAccess();

        na.setNode(0, 0, 0);
        na.setNode(1, 1, 0);
        na.setNode(2, 0, 1);

        GHUtility.setSpeed(60, true, true, encodingManager.getEncoder("car"), 
            graph.edge(0, 1).setDistance(1));
        GHUtility.setSpeed(60, true, true, encodingManager.getEncoder("car"), 
            graph.edge(1, 2).setDistance(1));
        GHUtility.setSpeed(60, true, true, encodingManager.getEncoder("car"), 
            graph.edge(2, 0).setDistance(1));

        // Create triangulation
        Triangulation triangulation = new Triangulation(graph, encodingManager.getBooleanEncodedValue("car_access"));
        triangulation.init();

        // Create ContourBuilder with real geometry factory
        ContourBuilder contourBuilder = new ContourBuilder(triangulation, new GeometryFactory());

        // Create a simple cut function that returns non-zero for some edges
        ToIntBiFunction<Vertex, Vertex> cut = (v1, v2) -> {
            // Return positive for some edges to generate rings
            if ((v1.getIndex() == 0 && v2.getIndex() == 1) || 
                (v1.getIndex() == 1 && v2.getIndex() == 2) || 
                (v1.getIndex() == 2 && v2.getIndex() == 0)) {
                return 1;
            }
            return 0;
        };

        // Get seed edges from triangulation
        Collection<ReadableQuadEdge> seedEdges = new ArrayList<>();
        for (ReadableQuadEdge edge : triangulation.getEdges()) {
            if (edge.isLive()) {
                seedEdges.add(edge);
                break; // Just need one to start
            }
        }

        // This should trigger the full chain ending with PreparedPolygon.getGeometry()
        contourBuilder.computeIsoline(cut, seedEdges);
    }
}

