            if (v1 == mockEdge2.orig() && v2 == mockEdge2.dest()) return -1;
            if (v1 == mockEdge3.orig() && v2 == mockEdge3.dest()) return 1;
            return 0;
        };

        // Create ContourBuilder instance
        ContourBuilder contourBuilder = new ContourBuilder(new GeometryFactory());

        // Execute the entry point method
        contourBuilder.computeIsoline(cut, seedEdges);
    }

    private ReadableQuadEdge createMockQuadEdge(int origId, int destId, double x1, double y1, double x2, double y2) {
        ReadableQuadEdge edge = Mockito.mock(ReadableQuadEdge.class);
        Object origVertex = new Object();
        Object destVertex = new Object();

        Mockito.when(edge.orig()).thenReturn(origVertex);
        Mockito.when(edge.dest()).thenReturn(destVertex);
        Mockito.when(edge.getPrimary()).thenReturn(edge);

        // Mock coordinate methods
        Coordinate coord1 = new Coordinate(x1, y1);
        Coordinate coord2 = new Coordinate(x2, y2);
        Mockito.when(edge.orig().getCoordinate()).thenReturn(coord1);
        Mockito.when(edge.dest().getCoordinate()).thenReturn(coord2);

        // Mock midpoint
        Coordinate mid = new Coordinate((x1 + x2) / 2, (y1 + y2) / 2);
        Object midPoint = Mockito.mock(Object.class);
        Mockito.when(midPoint.getCoordinate()).thenReturn(mid);
        Mockito.when(edge.orig().midPoint(Mockito.any())).thenReturn(midPoint);

        return edge;
    }

    private void linkQuadEdges(ReadableQuadEdge e1, ReadableQuadEdge e2, ReadableQuadEdge e3) {
        // Link e1 -> e2 -> e3 -> e1 in both directions
        Mockito.when(e1.oNext()).thenReturn(e2);
        Mockito.when(e1.oPrev()).thenReturn(e3);
        Mockito.when(e1.dNext()).thenReturn(e3);
        Mockito.when(e1.dPrev()).thenReturn(e2);

        Mockito.when(e2.oNext()).thenReturn(e3);
        Mockito.when(e2.oPrev()).thenReturn(e1);
        Mockito.when(e2.dNext()).thenReturn(e1);
        Mockito.when(e2.dPrev()).thenReturn(e3);

        Mockito.when(e3.oNext()).thenReturn(e1);
        Mockito.when(e3.oPrev()).thenReturn(e2);
        Mockito.when(e3.dNext()).thenReturn(e2);
        Mockito.when(e3.dPrev()).thenReturn(e1);
    }
}

