    @Test
    public void testCreateLandmarksTriggersIntHashSetConstructor() {
        // Create mocks for required constructor dependencies
        GraphHopperStorage graph = Mockito.mock(GraphHopperStorage.class);
        LMConfig lmConfig = Mockito.mock(LMConfig.class);
        Weighting weighting = Mockito.mock(Weighting.class);
        EncodingManager encodingManager = Mockito.mock(EncodingManager.class);

