        Mockito.when(lmConfig.getName()).thenReturn("test");

        // Create a mock AreaIndex to trigger the findBorderEdgeIds path
        AreaIndex<SplitArea> areaIndex = Mockito.mock(AreaIndex.class);

        // Create the LandmarkStorage instance with areaIndex set
        LandmarkStorage storage = new LandmarkStorage(graph, lmConfig, weighting, encodingManager);

        // Use reflection to set the areaIndex field since it's likely package-private or protected
        try {
            java.lang.reflect.Field areaIndexField = LandmarkStorage.class.getDeclaredField("areaIndex");
            areaIndexField.setAccessible(true);
            areaIndexField.set(storage, areaIndex);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        // Mock necessary graph methods
        Mockito.when(graph.getNodes()).thenReturn(10);
        Mockito.when(graph.getAllEdges()).thenReturn(Mockito.mock(AllEdgesIterator.class));

        // Mock the NodeAccess
        com.graphhopper.storage.NodeAccess nodeAccess = Mockito.mock(com.graphhopper.storage.NodeAccess.class);
        Mockito.when(graph.getNodeAccess()).thenReturn(nodeAccess);

        // Mock the encoded value lookup
        Mockito.when(encodingManager.hasEncodedValue(Mockito.anyString())).thenReturn(true);
        com.graphhopper.routing.ev.BooleanEncodedValue booleanEncodedValue = 
            Mockito.mock(com.graphhopper.routing.ev.BooleanEncodedValue.class);
        Mockito.when(encodingManager.getBooleanEncodedValue(Mockito.anyString())).thenReturn(booleanEncodedValue);

        // Mock the edge iterator to have at least one iteration
