        Mockito.when(graph.getAllEdges()).thenReturn(edgeIterator);
        Mockito.when(edgeIterator.next()).thenReturn(true).thenReturn(false);

        // Mock edge properties
        EdgeIteratorState edgeState = Mockito.mock(EdgeIteratorState.class);
        Mockito.when(edgeIterator.getEdge()).thenReturn(123);
        Mockito.when(edgeIterator.getBaseNode()).thenReturn(1);
        Mockito.when(edgeIterator.getAdjNode()).thenReturn(2);
        Mockito.when(edgeState.get(booleanEncodedValue)).thenReturn(false);

        // Mock the areaIndex query to return different areas for base and adj nodes
        // This will trigger the border condition in findBorderEdgeIds
        List<SplitArea> emptyList = Arrays.asList();
        List<SplitArea> singleAreaList = Arrays.asList(new SplitArea());

        Mockito.when(areaIndex.query(Mockito.anyDouble(), Mockito.anyDouble()))
