@Override
public void run() {
    try // PATH: Test should invoke the next PbfBlobDecoder.runAndTrapExceptions(...) [step in execution path]
    {
        runAndTrapExceptions();
        listener.complete(decodedEntities);
    } catch (RuntimeException e) {
        // exception is properly rethrown in PbfDecoder.sendResultsToSink
        listener.error(e);
    }
}

private void runAndTrapExceptions() {
    try {
        decodedEntities = new ArrayList<>();
        if ("OSMHeader".equals(blobType)) {
            // PATH: Test should invoke the next PbfBlobDecoder.readBlobContent(...) [step in execution path]
            processOsmHeader(readBlobContent());
        } else if ("OSMData".equals(blobType)) {
            processOsmPrimitives(readBlobContent());
        } else if (log.isDebugEnabled()) {
            log.debug("Skipping unrecognised blob type " + blobType);
        }
    } catch (IOException e) {
        throw new RuntimeException("Unable to process PBF blob", e);
    }
}

private byte[] readBlobContent() throws IOException {
    Fileformat.Blob blob = Fileformat.Blob.parseFrom(rawBlob);
    byte[] blobData;
    if (blob.hasRaw()) {
        blobData = blob.getRaw().toByteArray();
    } else // PATH: Test should invoke the next Fileformat$Blob.hasZlibData(...) [step in execution path]
    if (blob.hasZlibData()) {
        Inflater inflater = new Inflater();
        inflater.setInput(blob.getZlibData().toByteArray());
        blobData = new byte[blob.getRawSize()];
        try {
            inflater.inflate(blobData);
        } catch (DataFormatException e) {
            throw new RuntimeException("Unable to decompress PBF blob.", e);
        }
        if (!inflater.finished()) {
            throw new RuntimeException("PBF blob contains incomplete compressed data.");
        }
        inflater.end();
    } else {
        throw new RuntimeException("PBF blob uses unsupported compression, only raw or zlib may be used.");
    }
    return blobData;
}

