    try (DirectoryStream<Path> stream = Files.newDirectoryStream(bordersDirectory, "*.{geojson,json}")) {
        for (Path borderFile : stream) {
            try (BufferedReader reader = Files.newBufferedReader(borderFile, StandardCharsets.UTF_8)) {
